mapper.insert:
INSERT OR IGNORE INTO sdk_conversation_command (
    dispatch_key, caller_scope_digest, operation, idempotency_key_digest,
    request_digest, session_id, run_id, completed, result_revision, created_at
) VALUES (
    #{row.dispatchKey}, #{row.callerScopeDigest}, #{row.operation},
    #{row.idempotencyKeyDigest}, #{row.requestDigest}, #{row.sessionId},
    #{row.runId}, #{row.completed}, #{row.resultRevision}, #{row.createdAt}
)

mapper.select:
SELECT dispatch_key, caller_scope_digest, operation, idempotency_key_digest,
       request_digest, session_id, run_id, completed, result_revision, created_at
FROM sdk_conversation_command WHERE dispatch_key = #{dispatchKey}

SELECT dispatch_key, caller_scope_digest, operation, idempotency_key_digest,
       request_digest, session_id, run_id, completed, result_revision, created_at
FROM sdk_conversation_command
WHERE caller_scope_digest = #{callerScopeDigest}
  AND operation = #{operation}
  AND idempotency_key_digest = #{idempotencyKeyDigest}

mapper.update:
UPDATE sdk_conversation_command
SET run_id = #{runId}, completed = 1, result_revision = #{resultRevision}
WHERE dispatch_key = #{dispatchKey}
  AND (completed = 0 OR (run_id IS #{runId} AND result_revision = #{resultRevision}))

mapper.insert:
INSERT INTO sdk_conversation (
    session_id, tenant_id, principal_id, principal_type, display_name, status,
    active_run_id, active_run_version, active_dispatch_key,
    created_at, last_activity_at, revision
) VALUES (
    #{row.sessionId}, #{row.tenantId}, #{row.principalId}, #{row.principalType},
    #{row.displayName}, #{row.status}, #{row.activeRunId}, #{row.activeRunVersion},
    #{row.activeDispatchKey}, #{row.createdAt}, #{row.lastActivityAt}, #{row.revision}
)

mapper.select:
SELECT session_id, tenant_id, principal_id, principal_type, display_name, status,
       active_run_id, active_run_version, active_dispatch_key,
       created_at, last_activity_at, revision
FROM sdk_conversation
WHERE tenant_id = #{tenantId}
  AND principal_id = #{principalId}
  AND principal_type = #{principalType}
  AND status IN

      #{status}


  AND lower(display_name) LIKE '%' || lower(#{text}) || '%' ESCAPE '\'


  AND (last_activity_at < #{afterAt}
       OR (last_activity_at = #{afterAt} AND session_id < #{afterSessionId}))

ORDER BY last_activity_at DESC, session_id DESC
LIMIT #{limit}

mapper.update:
UPDATE sdk_conversation
SET active_dispatch_key = NULL,
    last_activity_at = #{at},
    revision = revision + 1
WHERE session_id = #{sessionId}
  AND revision = #{expectedRevision}
  AND active_dispatch_key = #{dispatchKey}
  AND active_run_id IS NULL

UPDATE sdk_conversation
SET active_run_id = NULL,
    active_run_version = NULL,
    last_activity_at = #{at},
    revision = revision + 1
WHERE session_id = #{sessionId}
  AND active_run_id = #{runId}
  AND revision = #{expectedRevision}

UPDATE sdk_conversation
SET display_name = #{displayName},
    last_activity_at = #{at},
    revision = revision + 1
WHERE session_id = #{sessionId}
  AND revision = #{expectedRevision}

UPDATE sdk_conversation
SET status = #{target},
    last_activity_at = #{at},
    revision = revision + 1
WHERE session_id = #{sessionId}
  AND revision = #{expectedRevision}
  AND status = #{expected}
  AND active_run_id IS NULL
  AND active_dispatch_key IS NULL
